import assert from 'node:assert/strict'
import {sha256} from '../../../packages/tianwen-evolution/src/learning-intake.ts'
import {parseConversationReadDenialReceipt as parse,verifyConversationReadDenialReceipt as verify} from '../../../packages/tianwen-evolution/src/conversation-read-denial.ts'
const reason='Only declared files: 界🙂\uFEFF\uFFFD',producer={id:'dev-native-file-policy.v1',digest:sha256('original reviewed producer')}
const call={type:'tool/call',seq:12,data:{name:'read',callId:'call-original',arguments:JSON.stringify({file_path:'scripts',offset:3}),turn:1,step:2}}
const result={type:'tool/result',seq:13,surfaceOp:'append',sourceEventSeqs:[12],data:{turn:1,step:2,message:{role:'user',source:{kind:'tool',callId:'call-original'},content:[{type:'tool-result',toolCallId:'call-original',isError:true,content:[{type:'text',text:'Error: '+reason}]}]}}}
const receipt=()=>({schemaVersion:'tianwen.native-read-denial.v1',identity:{taskId:'original-task',sessionId:'original-session',turn:1,callId:'call-original',rootCallId:'call-original'},callSeq:12,resultSeq:13,argumentsDigest:sha256(JSON.parse(call.data.arguments)),resultDigest:sha256(result),producer:structuredClone(producer),nativeTool:{package:'@deepseek-ai/dsh-tool-fs',version:'0.1.1-rc.2',adapter:'tianwen.file-ancillary.v1'},reason,dispatch:'not-dispatched'})
const binding=()=>({task:{taskId:'original-task',sessionId:'original-session',turn:1,startSeq:10},boundary:20,producerAdmissions:[structuredClone(producer)],events:[structuredClone(call),structuredClone(result)]})
