const input=receipt(),copy=parse(input);input.identity.taskId='changed';input.producer.id='changed';input.nativeTool.package='changed';assert.deepEqual(copy,receipt())
for(const invalid of [null,[],{}, {...receipt(),extra:1}, {...receipt(),dispatch:'dispatched'}, {...receipt(),schemaVersion:'other'}, {...receipt(),callSeq:13}, {...receipt(),resultSeq:0}, {...receipt(),callSeq:1.5}, {...receipt(),callSeq:Number.MAX_SAFE_INTEGER+1}, {...receipt(),argumentsDigest:'sha256:'+ 'A'.repeat(64)}, {...receipt(),resultDigest:'x'}, {...receipt(),reason:''}, {...receipt(),reason:' '}, {...receipt(),reason:'bad\0'}, {...receipt(),reason:'bad\ud800'}, {...receipt(),reason:'界'.repeat(1366)}])rejected(()=>parse(invalid))
for(const key of ['taskId','sessionId','callId','rootCallId'])for(const value of ['', ' ', 'x\0','x\ud801','界'.repeat(171)])rejected(()=>parse({...receipt(),identity:{...receipt().identity,[key]:value}}))
