for(const nativeTool of [{...receipt().nativeTool,package:'fake'}, {...receipt().nativeTool,version:'other'}, {...receipt().nativeTool,adapter:'fake'}, {...receipt().nativeTool,extra:1}])rejected(()=>parse({...receipt(),nativeTool}))
for(const value of [null,[],{id:'x',digest:'bad'},{id:'',digest:producer.digest},{...producer,extra:1}])rejected(()=>parse({...receipt(),producer:value}))
const symbolReceipt=receipt();symbolReceipt[Symbol('hidden')]=1;rejected(()=>parse(symbolReceipt))
const inherited=Object.create(receipt());rejected(()=>parse(inherited))
const exactBytes=receipt();exactBytes.reason='界'.repeat(1365)+'x';assert.equal(Buffer.byteLength(exactBytes.reason),4096);assert.deepEqual(parse(exactBytes),exactBytes)
const idBoundary=receipt();idBoundary.producer.id='界'.repeat(170)+'xx';assert.equal(Buffer.byteLength(idBoundary.producer.id),512);assert.deepEqual(parse(idBoundary),idBoundary)
for(const mutate of [b=>{b.task.taskId='other'},b=>{b.task.sessionId='other'},b=>{b.task.turn=2},b=>{b.task.startSeq=13},b=>{b.boundary=12},b=>{b.boundary=0},b=>{b.task.startSeq=0},b=>{b.producerAdmissions=[]},b=>{b.producerAdmissions[0].digest=sha256('other')},b=>{b.producerAdmissions[0].id='other'},b=>{b.producerAdmissions.push({...producer})},b=>{b.producerAdmissions=Array(1)},b=>{b.producerAdmissions.extra=1},b=>{b.producerAdmissions[Symbol('extra')]=1},b=>{b.producerAdmissions=Array.from({length:17},(_,i)=>({...producer,id:'id'+i}))}]){const b=binding();mutate(b);rejected(()=>verify(receipt(),b))}
for(const mutate of [b=>{b.events.shift()},b=>{b.events.pop()},b=>{b.events.push(structuredClone(call))},b=>{b.events.push(structuredClone(result))},b=>{b.events[0].data.name='write'},b=>{b.events[0].seq=11},b=>{b.events[0].data.turn=2},b=>{b.events[0].data.step=-1},b=>{b.events[0].data.arguments='null'},b=>{b.events[0].data.arguments='[]'},b=>{b.events[0].data.arguments='bad'},b=>{b.events[0].data.arguments=JSON.stringify({file_path:'other',offset:3})},b=>{b.events[0].data.arguments=JSON.stringify({file_path:4})},b=>{b.events[1].sourceEventSeqs=[11]},b=>{b.events[1].sourceEventSeqs=[12,12]},b=>{b.events[1].data.turn=2},b=>{b.events[1].data.step=3},b=>{b.events[1].data.error={name:'FsError'}},b=>{b.events[1].data.meta={fake:true}},b=>{b.events[1].data.message.content[0].isError=false},b=>{b.events[1].data.message.content[0].type='text'},b=>{b.events[1].data.message.content[0].content[0].text='Error: other'},b=>{b.events[1].data.message.content.push(structuredClone(b.events[1].data.message.content[0]))},b=>{b.events[1].data.message.content[0].content.push({type:'text',text:'extra'})},b=>{b.events[1].data.extra='changed event'},b=>{b.events[1].sourceEventSeqs.extra=1},b=>{b.events[1].data.message.content[Symbol('extra')]=1}]){const b=binding();mutate(b);rejected(()=>verify(receipt(),b))}
const rr=receipt(),beforeReceipt=JSON.stringify(rr),b=binding(),beforeBinding=JSON.stringify(b),verified=verify(rr,b);assert.equal(JSON.stringify(rr),beforeReceipt);assert.equal(JSON.stringify(b),beforeBinding)
verified.identity.taskId='changed';verified.producer.id='changed';verified.nativeTool.package='changed';assert.deepEqual(rr,receipt())
// Rebind fresh digests so these reject structure/provenance, not merely old hashes.
for(const mutate of [e=>{e.surfaceOp='rewrite'},e=>{delete e.surfaceOp},e=>{e.data.message.role='assistant'},e=>{e.data.message.source.kind='assistant'},e=>{e.data.message.content[0].toolCallId='other'},e=>{e.sourceEventSeqs=[12,12]},e=>{e.data.step=3},e=>{e.data.error={name:'FsError'}},e=>{e.data.meta={fake:true}},e=>{e.data.message.content[0].isError=false},e=>{e.data.message.content[0].content[0].text='Error: other'},e=>{e.data.message.content[0].content[0].type='image'}]){const bb=binding(),rr=receipt();mutate(bb.events[1]);rr.resultDigest=sha256(bb.events[1]);rejected(()=>verify(rr,bb))}
for(const value of ['null','[]',JSON.stringify({file_path:4})]){const bb=binding(),rr=receipt();bb.events[0].data.arguments=value;rr.argumentsDigest=sha256(JSON.parse(value));rejected(()=>verify(rr,bb))}
const unrelated=binding();unrelated.events.push({...structuredClone(call),seq:2},{...structuredClone(result),seq:3});assert.deepEqual(verify(receipt(),unrelated),receipt())
console.log(JSON.stringify({passed:true}))
